ALTER TABLE "clients" ADD COLUMN "public_token" text;--> statement-breakpoint
-- Existing clients get an unguessable token (2 x 122 random bits); new ones are generated by the app.
UPDATE "clients" SET "public_token" = replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');--> statement-breakpoint
CREATE UNIQUE INDEX "clients_public_token_uq" ON "clients" USING btree ("public_token");
